prelude:
export GIT_AUTHOR_NAME=Parity GIT_AUTHOR_EMAIL=parity@example.com GIT_COMMITTER_NAME=Parity GIT_COMMITTER_EMAIL=parity@example.com
export GIT_AUTHOR_DATE='1767225600 +0000' GIT_COMMITTER_DATE='1767225600 +0000'
commit() { git -C "$1" commit -q --allow-empty -m "$2"; }
commit_all() { git -C "$1" commit -q -a -m "$2"; }
branch_on() {
    local seed="$1" remote="$2" branch="$3" count="$4" i
    git -C "${seed}" checkout -q -b "${branch}" main
    for ((i = 1; i <= count; i++)); do commit "${seed}" "${branch} ${i}"; done
    git -C "${seed}" push -q "${remote}" "${branch}"
    git -C "${seed}" checkout -q main
}
